#!/usr/bin/env python3
"""todo_staleness_check.py — 賈維斯計畫 Phase 3 的解析邏輯
被 todo_staleness_check.sh 呼叫，不單獨執行。
用途：解析待辦表格列，找出「卡住超過7天」與「3天內到期」的項目。
"""
import hashlib
import json
import re
import sys
from datetime import date, datetime, timedelta

DONE_MARKS = ("✅", "🟢")
